"""A card's own source.

A card that draws data now filters a dataset of its own (dataset, filter_tree,
agg, measure, period_field: the definition a metric holds) unless it is a
single-value design over a saved metric. Charts and grouped cards were bound to
a metric before; this copies that metric's definition into each such card and
dashboard cell, so it keeps drawing the same thing. Its format, unit and colour
rules stay the metric's as the card's own options.style / options.thresholds,
where the card didn't set them itself. From here on the card no longer follows
edits to the metric.
"""

from django.db import migrations, models

SOURCE_KEYS = ("dataset", "filter_tree", "agg", "measure", "period_field")


def _own_source(cell, metric):
    """The cell with the metric's definition in place of the reference."""
    options = dict(cell.get("options") or {})
    style = dict(options.get("style") or {})
    if metric.format and metric.format != "number" and not style.get("format"):
        style["format"] = metric.format
    if metric.unit and not style.get("unit"):
        style["unit"] = metric.unit
    if style:
        options["style"] = style
    if metric.thresholds and "thresholds" not in options:
        options["thresholds"] = metric.thresholds
    out = {k: v for k, v in cell.items() if k != "metric"}
    out.update(
        {
            "dataset": metric.dataset,
            "filter_tree": metric.filter_tree or {},
            "agg": metric.agg or "count",
            "measure": metric.measure or "",
            "period_field": metric.period_field or "",
            "options": options,
        }
    )
    return out


def charts_filter_their_own_dataset(apps, schema_editor):
    Metric = apps.get_model("smallstack_dashboards", "Metric")
    Component = apps.get_model("smallstack_dashboards", "Component")
    Dashboard = apps.get_model("smallstack_dashboards", "Dashboard")
    metrics = {m.key: m for m in Metric.objects.filter(source="dataset")}

    # Saved cards: every design but the single stat.
    for card in Component.objects.exclude(type="metric").exclude(metric=""):
        metric = metrics.get(card.metric)
        if metric is None:
            continue  # a metric entered by hand or a rate: nothing to copy, the card keeps its reference
        cell = _own_source({"metric": card.metric, "options": card.options or {}}, metric)
        card.metric = ""
        for key in SOURCE_KEYS:
            setattr(card, key, cell[key])
        card.options = cell["options"]
        card.save(update_fields=["metric", *SOURCE_KEYS, "options"])

    # Dashboard cells: the same, whether the cell is the dashboard's own or a
    # copy of a saved card (a copy is refreshed from the card when it's next
    # saved; until then it has the same definition).
    for board in Dashboard.objects.all():
        changed = False
        layout = []
        for cell in board.layout or []:
            if isinstance(cell, dict) and cell.get("type") != "metric" and cell.get("metric"):
                metric = metrics.get(cell["metric"])
                if metric is not None:
                    cell = _own_source(cell, metric)
                    changed = True
            layout.append(cell)
        if changed:
            board.layout = layout
            board.save(update_fields=["layout"])



